1314	
1315	  status = getreg32(gmac_base + DMA_STATUS) &
1316	           getreg32(gmac_base + DMA_INTR_ENA);
1317	
1318	  if (!status)
1319	    {
1320	      return OK;
1321	    }
1322	
1323	  /* Write-1-to-clear the status bits */
1324	
1325	  putreg32(status & DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1326	
1327	  /* Handle normal interrupts */
1328	
1329	  if (status & DMA_STATUS_NIS)
1330	    {
1331	      /* Receive interrupt: notify upper half */
1332	
1333	      if (status & DMA_STATUS_RI)
1334	        {
