1362	        }
1363	
1364	      if (status & DMA_STATUS_RU)
1365	        {
1366	          ethwarn("RX Buffer Unavailable\n");
1367	        }
1368	
1369	      if (status & DMA_STATUS_TPS)
1370	        {
1371	          ethwarn("TX Process Stopped\n");
1372	        }
1373	
1374	      if (status & DMA_STATUS_RPS)
1375	        {
1376	          ethwarn("RX Process Stopped\n");
1377	        }
1378	
1379	      if (status & DMA_STATUS_OVF)
1380	        {
1381	          ethwarn("RX Overflow\n");
1382	        }
1383	
1384	      if (status & DMA_STATUS_UNF)
1385	        {
1386	          ethwarn("TX Underflow\n");
1387	        }
1388	    }
