1404	{
1405	  FAR struct sg2000_eth_priv_s *priv =
1406	      (FAR struct sg2000_eth_priv_s *)dev;
1407	  int ret;
1408	
1409	  ethinfo("ifup begin\n");
1410	
1411	  /* 1. Enable clocks and deassert resets */
1412	
1413	  gmac_clock_enable();
1414	
1415	  /* 2. Set GMAC_CORE_INIT (includes PS=MII mode) before PHY operations */
1416	
1417	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONTROL);
1418	
1419	  /* 3. Initialize EPHY via APB */
1420	
1421	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1422	
1423	  /* 4. Verify MDIO communication with PHY */
1424	
1425	  ret = mdio_verify_phy(priv->gmac_base);
1426	  if (ret < 0)
1427	    {
1428	      etherr("PHY not responding: %d\n", ret);
1429	      return ret;
1430	    }
1431	
1432	  ethinfo("MDIO operational, mdio_addr=0x%08" PRIX32
1433	          " mdio_data=0x%08" PRIX32 "\n",
1434	          getreg32(priv->gmac_base + GMAC_MII_ADDR),
1435	          getreg32(priv->gmac_base + GMAC_MII_DATA));
1436	
1437	  /* 5. Run EPHY full analog tuning (requires operational MDIO) */
1438	
1439	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1440	
1441	  /* 6. Allocate DMA resources (once) */
1442	
1443	  ret = alloc_dma(priv);
1444	  if (ret < 0)
1445	    {
1446	      etherr("alloc_dma failed: %d\n", ret);
1447	      return ret;
1448	    }
1449	
1450	  /* 7. Initialize descriptor rings */
1451	
1452	  init_desc_rings(priv);
1453	
1454	  /* 8. Set MAC address */
1455	
1456	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1457	
1458	  /* 9. Configure PHY (auto-negotiation) BEFORE starting DMA.
1459	   *    Starting DMA while the PHY is in reset causes the TX path to
1460	   *    stall (frames held in FIFO with no RMII link) and the RX path
1461	   *    to pick up garbage from an unstable RMII interface.
1462	   */
1463	
1464	  ret = phy_config_init(priv);
1465	  if (ret < 0)
1466	    {
1467	      etherr("PHY config failed: %d\n", ret);
1468	      return ret;
1469	    }
1470	
1471	  /* 10. Hardware setup: DMA reset, MAC core, DMA mode, start DMA.
1472	   *    Performed AFTER PHY is ready — clean RMII link and stable speed.
1473	   *    Note: gmac_set_speed_duplex() is called INSIDE hw_setup() after
1474	   *    dma_soft_reset() to avoid the reset clearing FES/DM bits.
1475	   */
1476	
1477	  ret = hw_setup(priv);
1478	  if (ret < 0)
1479	    {
1480	      etherr("hw_setup failed: %d\n", ret);
1481	      return ret;
1482	    }
1483	
1484	  /* 11. Ring RX doorbell and enable interrupts (last, after all HW init) */
1485	
1486	  rx_doorbell(priv->gmac_base);
1487	  ethinfo("Enabling IRQ %d (SG2000_IRQ_GMAC=%d NVIC_IRQ_FIRST=%d)\n",
1488	          priv->irq, SG2000_IRQ_GMAC, NVIC_IRQ_FIRST);
1489	  up_enable_irq(priv->irq);

