static void ephy_write_seq(uintptr_t base, const struct ephy_regval_s *seq,
                           unsigned int count)
{
  unsigned int i;

  for (i = 0; i < count; i++)
    {
      putreg32(seq[i].value, base + seq[i].offset);
    }
}

