959	
960	  /* --- Phase 2.2: Configure DMA Bus Mode ---
961	   * PBL=8, RPBL=8, FB=1 (fixed burst), USP=1 (separate PBL),
962	   * AAL=1 (address-aligned beats).  ATDS is NOT set (basic descriptors).
963	   * Use explicit constants; (DMA_PBL_8 & 0x3f) would be 0 (PBL field is
964	   * at bits 8-13, masking with 0x3f gives 0).
965	   */
966	
967	  val = DMA_PBL_8 | ((3 << DMA_RPBL_SHIFT) & DMA_RPBL_MASK) |
968	        DMA_FB | DMA_USP | DMA_AAL;
969	  putreg32(val, gmac_base + DMA_BUS_MODE);
970	
971	  /* --- Phase 2.3: Configure AXI bus ---
972	   * WR_OSR_LMT=1, RD_OSR_LMT=2, BLEN support for 4/8/16 beats.
