901	/****************************************************************************
902	 * Private Functions — MAC Address Configuration
903	 *
904	 * Reference: Manual §4.4 Step 6, §10.3 Phase 5.3
905	 ****************************************************************************/
906	
907	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
908	{
909	  uint32_t hi;
910	  uint32_t lo;
911	
912	  hi = ((uint32_t)mac[5] << 8) | (uint32_t)mac[4] | GMAC_HI_REG_AE;
913	  lo = ((uint32_t)mac[3] << 24) | ((uint32_t)mac[2] << 16) |
914	       ((uint32_t)mac[1] << 8)  | (uint32_t)mac[0];
915	
916	  putreg32(hi, gmac_base + GMAC_MAC_ADDR0_HIGH);
917	  putreg32(lo, gmac_base + GMAC_MAC_ADDR0_LOW);
918	
919	  ethinfo("MAC addr set: %02x:%02x:%02x:%02x:%02x:%02x\n",
920	          mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
921	}
922	
923	/****************************************************************************
924	 * Private Functions — MAC Core and DMA Initialization
925	 *
926	 * Performs the full hardware initialization sequence:
927	 *   - DMA bus mode and AXI configuration
928	 *   - MAC core init (GMAC_CONTROL, interrupt mask, frame filter)
929	 *   - DMA operation mode (Store-and-Forward)
930	 *   - Interrupt enable
931	 *   - Write descriptor base addresses
932	 *   - Start DMA TX and RX
933	 *
934	 * Reference: Manual §10.3 Phase 2, 5, 6, 7
935	 ****************************************************************************/
936	
937	static void gmac_set_speed_duplex(uintptr_t gmac_base, int speed, int duplex);
938	
939	static int hw_setup(struct sg2000_eth_priv_s *priv)
940	{
941	  uintptr_t gmac_base = priv->gmac_base;
942	  uint32_t val;
943	
944	  /* --- Phase 2: DMA software reset ---
945	   * Note: This resets the entire GMAC block including GMAC_CONTROL.
946	   * Speed/duplex must be configured AFTER this point.
947	   */
948	
949	  if (dma_soft_reset(gmac_base) < 0)
950	    {
951	      return -ETIMEDOUT;
952	    }
953	
954	  /* --- Phase 2.1: Apply negotiated speed/duplex to GMAC ---
955	   * Must be done AFTER dma_soft_reset() which clears GMAC_CONTROL.
956	   */
957	
958	  gmac_set_speed_duplex(gmac_base, priv->speed, priv->duplex);
959	
960	  /* --- Phase 2.2: Configure DMA Bus Mode ---
961	   * PBL=8, RPBL=8, FB=1 (fixed burst), USP=1 (separate PBL),
962	   * AAL=1 (address-aligned beats).  ATDS is NOT set (basic descriptors).
963	   * Use explicit constants; (DMA_PBL_8 & 0x3f) would be 0 (PBL field is
964	   * at bits 8-13, masking with 0x3f gives 0).
965	   */
966	
967	  val = DMA_PBL_8 | ((3 << DMA_RPBL_SHIFT) & DMA_RPBL_MASK) |
968	        DMA_FB | DMA_USP | DMA_AAL;
969	  putreg32(val, gmac_base + DMA_BUS_MODE);
970	
971	  /* --- Phase 2.3: Configure AXI bus ---
972	   * WR_OSR_LMT=1, RD_OSR_LMT=2, BLEN support for 4/8/16 beats.
973	   */
974	
975	  putreg32((1 << DMA_AXI_WR_OSR_LMT_SHIFT) |
976	           (2 << DMA_AXI_RD_OSR_LMT_SHIFT) |
977	           (0xf << DMA_AXI_BLEN_SHIFT),
978	           gmac_base + DMA_AXI_BUS_MODE);
979	
980	  ethinfo("DMA: bus_mode=0x%08" PRIX32 " axi=0x%08" PRIX32 "\n",
981	          getreg32(gmac_base + DMA_BUS_MODE),
982	          getreg32(gmac_base + DMA_AXI_BUS_MODE));
983	
984	  /* --- Phase 5.1: Configure GMAC_CONTROL ---
985	   * Use read-modify-write to preserve speed/duplex (FES, DM) already
986	   * set by gmac_set_speed_duplex() before hw_setup() was called.
987	   */
988	
989	  val = getreg32(gmac_base + GMAC_CONTROL);
990	  ethinfo("hw_setup phase 5.1: before=0x%08" PRIX32
991	          " FES=%d DM=%d\n", val,
992	          !!(val & GMAC_CONTROL_FES), !!(val & GMAC_CONTROL_DM));
993	  putreg32(val | GMAC_CORE_INIT, gmac_base + GMAC_CONTROL);
994	  ethinfo("hw_setup phase 5.1: after=0x%08" PRIX32 "\n",
995	          getreg32(gmac_base + GMAC_CONTROL));
996	
997	  /* --- Phase 5.2: Configure GMAC_INT_MASK (disable all MAC interrupts,
998	   *   use DMA interrupts only) ---
999	   */
1000	
1001	  putreg32(GMAC_INT_DEFAULT_MASK, gmac_base + GMAC_INT_MASK);
1002	
1003	  /* --- Phase 5.4: Configure frame filter ---
1004	   * Use promiscuous mode (PR) to accept all packets.  This matches the
1005	   * old driver's setup and avoids MAC address filtering issues.
1006	   */
1007	
1008	  putreg32(GMAC_FILTER_PR | GMAC_FILTER_HMC | GMAC_FILTER_PM,
1009	           gmac_base + GMAC_FRAME_FILTER);
1010	
1011	  /* Clear VLAN tag */
1012	
1013	  putreg32(0, gmac_base + GMAC_VLAN_TAG);
1014	
1015	  /* Clear pending MAC and DMA interrupts */
1016	
1017	  putreg32(0xffffffff, gmac_base + GMAC_INT_STATUS);
1018	  putreg32(DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1019	
1020	  /* --- Phase 5.5: Enable MAC TX and RX --- */
1021	
1022	  val = getreg32(gmac_base + GMAC_CONTROL);
1023	  putreg32(val | GMAC_CONTROL_TE | GMAC_CONTROL_RE, gmac_base + GMAC_CONTROL);
1024	
1025	  /* --- Phase 6.1: Configure DMA operation mode ---
1026	   * RSF=1 (RX Store-and-Forward), TSF=1 (TX Store-and-Forward),
1027	   * OSF=1 (Operate on Second Frame), RTC=64, TTC=64.
1028	   */
1029	
1030	  val = getreg32(gmac_base + DMA_CONTROL);
1031	  val |= DMA_CONTROL_RSF | DMA_CONTROL_TSF | DMA_CONTROL_OSF |
1032	         DMA_CONTROL_RTC_64 | DMA_CONTROL_TTC_64;
1033	  putreg32(val, gmac_base + DMA_CONTROL);
1034	
1035	  /* --- Phase 6.2: Enable DMA interrupts --- */
1036	
1037	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
1038	
1039	  /* --- Phase 7.1: Write descriptor base addresses --- */
1040	
1041	  putreg32(priv->tx_desc_phys, gmac_base + DMA_TX_BASE_ADDR);
1042	  putreg32(priv->rx_desc_phys, gmac_base + DMA_RCV_BASE_ADDR);
1043	
1044	  /* --- Phase 7.2-7.3: Start DMA TX and RX ---
1045	   * Write ST first, then SR separately with a delay.  The hardware
1046	   * may ignore SR if written simultaneously with ST.
1047	   */
1048	
1049	  val = getreg32(gmac_base + DMA_CONTROL);
1050	  putreg32(val | DMA_CONTROL_ST, gmac_base + DMA_CONTROL);
1051	  up_udelay(10);
1052	
1053	  val = getreg32(gmac_base + DMA_CONTROL);
1054	  putreg32(val | DMA_CONTROL_SR, gmac_base + DMA_CONTROL);
1055	  up_udelay(10);
1056	
1057	  /* Diagnostic dump: verify all critical RX-path registers after hw_setup */
1058	
1059	  {
1060	    uint32_t gmac_ctrl  = getreg32(gmac_base + GMAC_CONTROL);
1061	    uint32_t dma_ctrl   = getreg32(gmac_base + DMA_CONTROL);
1062	    uint32_t dma_status = getreg32(gmac_base + DMA_STATUS);
1063	    uint32_t dma_intr   = getreg32(gmac_base + DMA_INTR_ENA);
1064	    uint32_t frame_flt  = getreg32(gmac_base + GMAC_FRAME_FILTER);
1065	    uint32_t gmac_debug = getreg32(gmac_base + GMAC_DEBUG);
1066	    uint32_t rcv_base   = getreg32(gmac_base + DMA_RCV_BASE_ADDR);
1067	    uint32_t cur_rx_desc = getreg32(gmac_base + DMA_HOST_RX_DESC);
1068	    uint32_t cur_rx_buf  = getreg32(gmac_base + DMA_CUR_RX_BUF_ADDR);
1069	    uint32_t rx_dma_state = (dma_status >> 17) & 0x7;  /* bits 19:17 = RS */
1070	    uint32_t tx_dma_state = (dma_status >> 20) & 0x7;  /* bits 22:20 = TS */
1071	    uint32_t rxfsts = (gmac_debug >> 8) & 0x3;         /* bits 9:8 = RXFSTS */
1072	
1073	    ethinfo("hw_setup diag:\n");
1074	    ethinfo("  GMAC_CONTROL    =0x%08" PRIX32 " RE=%d TE=%d FES=%d DM=%d\n",
1075	            gmac_ctrl, !!(gmac_ctrl & GMAC_CONTROL_RE),
1076	            !!(gmac_ctrl & GMAC_CONTROL_TE),
1077	            !!(gmac_ctrl & GMAC_CONTROL_FES),
1078	            !!(gmac_ctrl & GMAC_CONTROL_DM));
1079	    ethinfo("  GMAC_FRAME_FILT =0x%08" PRIX32 " PR=%d RA=%d PM=%d\n",
1080	            frame_flt, !!(frame_flt & GMAC_FILTER_PR),
1081	            !!(frame_flt & GMAC_FILTER_RA),
1082	            !!(frame_flt & GMAC_FILTER_PM));
1083	    ethinfo("  GMAC_DEBUG      =0x%08" PRIX32 " RXFSTS=%d\n",
1084	            gmac_debug, rxfsts);
1085	    ethinfo("  DMA_CONTROL     =0x%08" PRIX32 " SR=%d ST=%d RSF=%d\n",
1086	            dma_ctrl, !!(dma_ctrl & DMA_CONTROL_SR),
1087	            !!(dma_ctrl & DMA_CONTROL_ST),
1088	            !!(dma_ctrl & DMA_CONTROL_RSF));
1089	    ethinfo("  DMA_STATUS      =0x%08" PRIX32
1090	            " RS=%d(%s) TS=%d(%s) RI=%d TI=%d RU=%d RPS=%d\n",
1091	            dma_status, rx_dma_state,
1092	            rx_dma_state == 0 ? "Stopped" :
1093	            rx_dma_state == 1 ? "FetchDesc" :
1094	            rx_dma_state == 3 ? "WaitPkt" :
1095	            rx_dma_state == 4 ? "Suspended" :
1096	            rx_dma_state == 7 ? "XferData" : "other",
1097	            tx_dma_state,
1098	            tx_dma_state == 0 ? "Stopped" :
1099	            tx_dma_state == 1 ? "FetchDesc" :
1100	            tx_dma_state == 3 ? "ReadData" :
1101	            tx_dma_state == 7 ? "CloseDesc" : "other",
1102	            !!(dma_status & DMA_STATUS_RI),
1103	            !!(dma_status & DMA_STATUS_TI),
1104	            !!(dma_status & DMA_STATUS_RU),
1105	            !!(dma_status & DMA_STATUS_RPS));
1106	    ethinfo("  DMA_INTR_ENA    =0x%08" PRIX32 " RIE=%d TIE=%d NIE=%d\n",
1107	            dma_intr, !!(dma_intr & DMA_INTR_RIE),
1108	            !!(dma_intr & DMA_INTR_TIE),
1109	            !!(dma_intr & DMA_INTR_NIE));
1110	    ethinfo("  DMA_RCV_BASE    =0x%08" PRIX32
1111	            " (expected=0x%08" PRIX32 ")\n",
1112	            rcv_base, (uint32_t)priv->rx_desc_phys);
1113	    ethinfo("  DMA_HOST_RX_DESC=0x%08" PRIX32
1114	            " DMA_CUR_RX_BUF=0x%08" PRIX32 "\n",
1115	            cur_rx_desc, cur_rx_buf);
1116	
1117	    /* Dump first RX descriptor as DMA sees it */
1118	
1119	    {
1120	      struct sg2000_dma_desc_s *rx0 = &priv->rx_desc[0];
1121	      dcache_invalidate_range((uintptr_t)rx0,
1122	                              (uintptr_t)rx0 +
1123	                              sizeof(struct sg2000_dma_desc_s));
1124	      ethinfo("  RX desc[0]: des0=0x%08" PRIX32 " des1=0x%08" PRIX32
1125	              " des2=0x%08" PRIX32 " OWN=%d\n",
1126	              rx0->des0, rx0->des1, rx0->des2,
1127	              !!(rx0->des0 & RDES0_OWN));
1128	    }
1129	  }
1130	
1131	  return OK;
1132	}
