1134	/****************************************************************************
1135	 * Name: gmac_set_speed_duplex
1136	 *
1137	 * Description:
1138	 *   Configure GMAC speed and duplex mode based on PHY negotiation result.
1139	 *
1140	 * Reference: Manual §10.9
1141	 ****************************************************************************/
1142	
1143	static void gmac_set_speed_duplex(uintptr_t gmac_base, int speed, int duplex)
1144	{
1145	  uint32_t val;
1146	
1147	  val = getreg32(gmac_base + GMAC_CONTROL);
1148	  ethinfo("gmac_set_speed_duplex: before=0x%08" PRIX32
1149	          " speed=%d duplex=%d\n", val, speed, duplex);
1150	
1151	  /* Clear speed and duplex bits */
1152	
1153	  val &= ~(GMAC_CONTROL_FES | GMAC_CONTROL_DM);
1154	
1155	  /* Set speed: FES=1 for 100Mbps, FES=0 for 10Mbps */
1156	
1157	  if (speed == 100)
1158	    {
1159	      val |= GMAC_CONTROL_FES;
1160	    }
1161	
1162	  /* Set duplex: DM=1 for full duplex */
1163	
1164	  if (duplex)
1165	    {
1166	      val |= GMAC_CONTROL_DM;
1167	    }
1168	
1169	  putreg32(val, gmac_base + GMAC_CONTROL);
1170	  ethinfo("gmac_set_speed_duplex: after=0x%08" PRIX32 "\n",
1171	          getreg32(gmac_base + GMAC_CONTROL));
1172	}
