1174	/****************************************************************************
1175	 * Private Functions — DMA Doorbell
1176	 *
1177	 * Writing any value to DMA_XMT_POLL_DEMAND / DMA_RCV_POLL_DEMAND
1178	 * triggers the DMA engine to re-fetch descriptors from the ring.
1179	 *
1180	 * Reference: Manual §2.3, §10.4, §10.5
1181	 ****************************************************************************/
1182	
1183	static void tx_doorbell(uintptr_t gmac_base)
1184	{
1185	  putreg32(0, gmac_base + DMA_XMT_POLL_DEMAND);
1186	}
1187	
1188	static void rx_doorbell(uintptr_t gmac_base)
1189	{
1190	  putreg32(0, gmac_base + DMA_RCV_POLL_DEMAND);
1191	}
1192	
1193	/****************************************************************************
1194	 * Private Functions — Hardware Transmit
1195	 *
1196	 * Prepares a TX descriptor, copies data to the DMA buffer, and signals
1197	 * the DMA engine to transmit.
1198	 *
1199	 * Reference: Manual §5.2, §10.4
1200	 ****************************************************************************/
1201	
1202	static int hw_transmit(struct sg2000_eth_priv_s *priv,
1203	                       const uint8_t *data, unsigned int len)
1204	{
1205	  uintptr_t gmac_base = priv->gmac_base;
1206	  unsigned int idx = priv->tx_cur;
1207	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1208	  irqstate_t flags;
1209	
1210	  /* Check if ring is full */
1211	
1212	  if (desc->des0 & TDES0_OWN)
1213	    {
1214	      return -EBUSY;
1215	    }
1216	
1217	  /* Copy data to pre-allocated TX DMA buffer.
1218	   * Skip if data already points to our DMA buffer (fragmented packets
1219	   * are pre-copied by netdriver_transmit).
1220	   */
1221	
1222	  if (data != priv->tx_buf[idx])
1223	    {
1224	      memcpy(priv->tx_buf[idx], data, len);
1225	    }
1226	
1227	  /* Debug: dump TX buffer address and first bytes of packet data */
1228	
1229	  ethinfo("TX[%u] virt=%p phys=0x%08" PRIX32 " len=%u\n",
1230	          idx, priv->tx_buf[idx], priv->tx_buf_phys[idx], len);
1231	  ethinfo("TX[%u] data: %02x %02x %02x %02x %02x %02x "
1232	          "%02x %02x %02x %02x %02x %02x %02x %02x\n",
1233	          idx,
1234	          priv->tx_buf[idx][0], priv->tx_buf[idx][1],
1235	          priv->tx_buf[idx][2], priv->tx_buf[idx][3],
1236	          priv->tx_buf[idx][4], priv->tx_buf[idx][5],
1237	          priv->tx_buf[idx][6], priv->tx_buf[idx][7],
1238	          priv->tx_buf[idx][8], priv->tx_buf[idx][9],
1239	          priv->tx_buf[idx][10], priv->tx_buf[idx][11],
1240	          priv->tx_buf[idx][12], priv->tx_buf[idx][13]);
1241	
1242	  /* Write back TX buffer so DMA can see packet data */
1243	
1244	  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
1245	                     (uintptr_t)priv->tx_buf[idx] + len);
1246	
1247	  /* Fill descriptor (basic format, 16 bytes):
1248	   *   des0: OWN + IC
1249	   *   des1: buffer size + FS + LS + END_RING + IC
1250	   *   des2: buffer physical address
1251	   */
1252	
1253	  desc->des2 = priv->tx_buf_phys[idx];
1254	  desc->des1 = (len & TDES1_BUFFER1_SIZE_MASK) |
1255	               TDES1_FIRST_SEGMENT | TDES1_LAST_SEGMENT |
1256	               ((idx == (TX_RING_SIZE - 1)) ? TDES1_END_RING : 0) |
1257	               TDES1_INTERRUPT;
1258	
1259	  /* Memory barrier: ensure descriptor writes are visible to DMA
1260	   * before setting OWN=1.
1261	   */
1262	
1263	  dcache_clean_range((uintptr_t)desc,
1264	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1265	  __asm__ volatile ("fence w,w" ::: "memory");
1266	
1267	  /* Give ownership to DMA.  IC and END_RING are set in des1 above. */
1268	
1269	  desc->des0 = TDES0_OWN;
1270	
1271	  dcache_clean_range((uintptr_t)desc,
1272	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1273	
1274	  /* Advance TX pointer and ring doorbell */
1275	
1276	  flags = up_irq_save();
1277	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1278	  tx_doorbell(gmac_base);
1279	  up_irq_restore(flags);
1280	
1281	  ethinfo("TX: %u bytes desc[%u] des0=0x%08" PRIX32
1282	          " des1=0x%08" PRIX32 " des2=0x%08" PRIX32
1283	          " dma_status=0x%08" PRIX32 "\n",
1284	          len, idx, desc->des0, desc->des1, desc->des2,
1285	          getreg32(gmac_base + DMA_STATUS));
1286	
1287	  return OK;
1288	}
1289	
1290	/****************************************************************************
1291	 * Private Functions — TX Cleanup
1292	 *
1293	 * Frees completed TX packets by walking from dirty_tx to cur_tx.
1294	 * Called from ISR on TX Complete interrupt.
1295	 *
1296	 * Reference: Manual §5.3, §10.4 step 7
1297	 ****************************************************************************/
1298	
1299	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1300	{
1301	  irqstate_t flags = up_irq_save();
1302	
1303	  while (priv->tx_dirty != priv->tx_cur)
1304	    {
1305	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1306	
1307	      /* Invalidate descriptor cache line to read DMA-written status */
1308	
1309	      dcache_invalidate_range((uintptr_t)desc,
1310	                              (uintptr_t)desc +
1311	                              sizeof(struct sg2000_dma_desc_s));
1312	
1313	      if (desc->des0 & TDES0_OWN)
1314	        {
1315	          break;  /* Still owned by DMA */
1316	        }
1317	
1318	      /* Check for TX errors */
1319	
1320	      if (desc->des0 & TDES0_ERROR_SUMMARY)
1321	        {
1322	          etherr("TX error desc[%u] status=0x%08" PRIX32 "\n",
1323	                 priv->tx_dirty, desc->des0);
1324	        }
1325	
1326	      /* Free the tracked netpkt and notify upper half */
1327	
1328	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1329	        {
1330	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1331	          priv->tx_pkt[priv->tx_dirty] = NULL;
1332	          netdev_lower_txdone(&priv->dev);
1333	        }
1334	
1335	      /* Clear descriptor for reuse, END_RING=1 on all (CV181x convention) */
1336	
1337	      desc->des0 = 0;
1338	      desc->des1 = (priv->tx_dirty == (TX_RING_SIZE - 1)) ?
1339	                   TDES1_END_RING : 0;
1340	
1341	      dcache_clean_range((uintptr_t)desc,
1342	                         (uintptr_t)desc +
1343	                         sizeof(struct sg2000_dma_desc_s));
1344	
1345	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1346	    }
1347	
1348	  up_irq_restore(flags);
1349	}
1350	
1351	/****************************************************************************
1352	 * Private Functions — Interrupt Service Routine
1353	 *
1354	 * Reads DMA_STATUS to determine interrupt cause and dispatches accordingly.
1355	 * All DMA status bits are write-1-to-clear.
1356	 *
1357	 * Reference: Manual §7, §10.6
1358	 ****************************************************************************/
1359	
1360	static int sg2000_eth_isr(int irq, void *context, void *arg)
1361	{
1362	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1363	  uintptr_t gmac_base = priv->gmac_base;
1364	  uint32_t status;
1365	  uint32_t mac_status;
1366	
1367	  /* Always print when ISR is entered (helps debug interrupt delivery) */
1368	
1369	  /* Read and clear MAC interrupts (if any) */
1370	
1371	  mac_status = getreg32(gmac_base + GMAC_INT_STATUS);
1372	  if (mac_status)
1373	    {
1374	      putreg32(mac_status, gmac_base + GMAC_INT_STATUS);
1375	    }
1376	
1377	  /* Read DMA status masked by enabled interrupts */
1378	
1379	  status = getreg32(gmac_base + DMA_STATUS) &
1380	           getreg32(gmac_base + DMA_INTR_ENA);
1381	
1382	  if (!status)
1383	    {
1384	      return OK;
1385	    }
1386	
1387	  /* Write-1-to-clear the status bits */
1388	
1389	  putreg32(status & DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1390	
1391	  /* Handle normal interrupts */
1392	
1393	  if (status & DMA_STATUS_NIS)
1394	    {
1395	      /* Receive interrupt: notify upper half */
1396	
1397	      if (status & DMA_STATUS_RI)
1398	        {
1399	          ethinfo("ISR: RX interrupt, status=0x%08" PRIX32 "\n", status);
1400	          netdev_lower_rxready(&priv->dev);
1401	        }
1402	
1403	      /* Transmit complete: clean up descriptors */
1404	
1405	      if (status & DMA_STATUS_TI)
1406	        {
1407	          ethinfo("ISR: TX interrupt, status=0x%08" PRIX32 "\n", status);
1408	          tx_cleanup(priv);
1409	        }
1410	    }
1411	
1412	  /* Handle abnormal interrupts */
1413	
1414	  if (status & DMA_STATUS_AIS)
1415	    {
1416	      if (status & DMA_STATUS_FBI)
1417	        {
1418	          etherr("Fatal Bus Error! bus_mode=0x%08" PRIX32
1419	                 " dma_status=0x%08" PRIX32 "\n",
1420	                 getreg32(gmac_base + DMA_BUS_MODE), status);
1421	        }
1422	
1423	      if (status & DMA_STATUS_TU)
1424	        {
1425	          ethwarn("TX Buffer Unavailable\n");
1426	        }
1427	
1428	      if (status & DMA_STATUS_RU)
1429	        {
1430	          ethwarn("RX Buffer Unavailable\n");
1431	        }
1432	
1433	      if (status & DMA_STATUS_TPS)
1434	        {
1435	          ethwarn("TX Process Stopped\n");
1436	        }
1437	
1438	      if (status & DMA_STATUS_RPS)
1439	        {
1440	          ethwarn("RX Process Stopped\n");
1441	        }
1442	
1443	      if (status & DMA_STATUS_OVF)
1444	        {
1445	          ethwarn("RX Overflow\n");
1446	        }
1447	
1448	      if (status & DMA_STATUS_UNF)
1449	        {
1450	          ethwarn("TX Underflow\n");
1451	        }
1452	    }
1453	
1454	  return OK;
1455	}
