1457	/****************************************************************************
1458	 * Name: netdriver_ifup
1459	 *
1460	 * Description:
1461	 *   OpenVela netdev_ops_s ifup callback.  Performs the full hardware
1462	 *   initialization sequence and brings the interface online.
1463	 *
1464	 * Reference: Manual §4.3, §10.3, §10.11
1465	 ****************************************************************************/
1466	
1467	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1468	{
1469	  FAR struct sg2000_eth_priv_s *priv =
1470	      (FAR struct sg2000_eth_priv_s *)dev;
1471	  int ret;
1472	
1473	  ethinfo("ifup begin\n");
1474	
1475	  /* 1. Enable clocks and deassert resets */
1476	
1477	  gmac_clock_enable();
1478	
1479	  /* 2. Set GMAC_CORE_INIT (includes PS=MII mode) before PHY operations */
1480	
1481	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONTROL);
1482	
1483	  /* 3. Initialize EPHY via APB */
1484	
1485	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1486	
1487	  /* 4. Verify MDIO communication with PHY */
1488	
1489	  ret = mdio_verify_phy(priv->gmac_base);
1490	  if (ret < 0)
1491	    {
1492	      etherr("PHY not responding: %d\n", ret);
1493	      return ret;
1494	    }
1495	
1496	  ethinfo("MDIO operational, mdio_addr=0x%08" PRIX32
1497	          " mdio_data=0x%08" PRIX32 "\n",
1498	          getreg32(priv->gmac_base + GMAC_MII_ADDR),
1499	          getreg32(priv->gmac_base + GMAC_MII_DATA));
1500	
1501	  /* 5. Run EPHY full analog tuning (requires operational MDIO) */
1502	
1503	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1504	
1505	  /* 6. Allocate DMA resources (once) */
1506	
1507	  ret = alloc_dma(priv);
1508	  if (ret < 0)
1509	    {
1510	      etherr("alloc_dma failed: %d\n", ret);
1511	      return ret;
1512	    }
1513	
1514	  /* 7. Initialize descriptor rings */
1515	
1516	  init_desc_rings(priv);
1517	
1518	  /* 8. Set MAC address */
1519	
1520	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1521	
1522	  /* 9. Configure PHY (auto-negotiation) BEFORE starting DMA.
1523	   *    Starting DMA while the PHY is in reset causes the TX path to
1524	   *    stall (frames held in FIFO with no RMII link) and the RX path
1525	   *    to pick up garbage from an unstable RMII interface.
1526	   */
1527	
1528	  ret = phy_config_init(priv);
1529	  if (ret < 0)
1530	    {
1531	      etherr("PHY config failed: %d\n", ret);
1532	      return ret;
1533	    }
1534	
1535	  /* 10. Hardware setup: DMA reset, MAC core, DMA mode, start DMA.
1536	   *    Performed AFTER PHY is ready — clean RMII link and stable speed.
1537	   *    Note: gmac_set_speed_duplex() is called INSIDE hw_setup() after
1538	   *    dma_soft_reset() to avoid the reset clearing FES/DM bits.
1539	   */
1540	
1541	  ret = hw_setup(priv);
1542	  if (ret < 0)
1543	    {
1544	      etherr("hw_setup failed: %d\n", ret);
1545	      return ret;
1546	    }
1547	
1548	  /* 11. Ring RX doorbell and enable interrupts (last, after all HW init) */
1549	
1550	  rx_doorbell(priv->gmac_base);
1551	  ethinfo("Enabling IRQ %d (SG2000_IRQ_GMAC=%d NVIC_IRQ_FIRST=%d)\n",
1552	          priv->irq, SG2000_IRQ_GMAC, NVIC_IRQ_FIRST);
1553	  up_enable_irq(priv->irq);
1554	
1555	  /* 12. Signal carrier on to the network stack (if link detected) */
1556	
1557	  if (priv->link_up)
1558	    {
1559	      netdev_lower_carrier_on(dev);
1560	    }
1561	
1562	  ethinfo("ifup done: %d Mbps %s duplex, link=%s\n",
1563	          priv->speed, priv->duplex ? "Full" : "Half",
1564	          priv->link_up ? "up" : "down");
1565	
1566	  return OK;
1567	}
1568	
1569	/****************************************************************************
1570	 * Name: netdriver_ifdown
1571	 *
1572	 * Description:
1573	 *   OpenVela netdev_ops_s ifdown callback.  Stops DMA, disables MAC,
1574	 *   and disables interrupts.
1575	 *
1576	 * Reference: Manual §4.3
1577	 ****************************************************************************/
1578	
1579	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1580	{
1581	  FAR struct sg2000_eth_priv_s *priv =
1582	      (FAR struct sg2000_eth_priv_s *)dev;
1583	  uintptr_t gmac_base = priv->gmac_base;
1584	  uint32_t val;
1585	
1586	  up_disable_irq(priv->irq);
1587	
1588	  /* Stop TX and RX DMA */
1589	
1590	  val = getreg32(gmac_base + DMA_CONTROL);
1591	  putreg32(val & ~(DMA_CONTROL_ST | DMA_CONTROL_SR), gmac_base + DMA_CONTROL);
1592	
1593	  /* Disable MAC TX/RX */
1594	
1595	  val = getreg32(gmac_base + GMAC_CONTROL);
1596	  putreg32(val & ~(GMAC_CONTROL_TE | GMAC_CONTROL_RE),
1597	           gmac_base + GMAC_CONTROL);
1598	
1599	  /* Disable DMA interrupts */
1600	
1601	  putreg32(0, gmac_base + DMA_INTR_ENA);
1602	
1603	  /* Clear pending interrupts */
1604	
1605	  putreg32(DMA_STATUS_W1C_MASK, gmac_base + DMA_STATUS);
1606	
1607	  netdev_lower_carrier_off(dev);
1608	
1609	  priv->link_up = 0;
1610	
1611	  ethinfo("ifdown: interface stopped\n");
1612	
1613	  return OK;
1614	}
1615	
1616	/****************************************************************************
1617	 * Name: netdriver_transmit
1618	 *
1619	 * Description:
1620	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet via DMA.
1621	 *   The driver takes ownership of the netpkt and MUST free it after
1622	 *   TX completion (in tx_cleanup) or on error.
1623	 *
1624	 * Reference: Manual §5.1, §10.4
1625	 ****************************************************************************/
1626	
1627	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1628	                               FAR netpkt_t *pkt)
1629	{
1630	  FAR struct sg2000_eth_priv_s *priv =
1631	      (FAR struct sg2000_eth_priv_s *)dev;
1632	  unsigned int len = netpkt_getdatalen(dev, pkt);
1633	  const uint8_t *data;
1634	  irqstate_t flags;
1635	  int ret;
1636	
1637	  if (len > TX_BUF_SIZE)
1638	    {
1639	      etherr("TX packet too large: %u\n", len);
1640	      return -E2BIG;
1641	    }
1642	
1643	  /* For non-fragmented packets, use the data pointer directly.
1644	   * hw_transmit() will memcpy it into the DMA TX buffer.
1645	   * For fragmented packets, copy directly into the DMA TX buffer
1646	   * to avoid a stack-allocated temporary buffer.
1647	   */
1648	
1649	  if (netpkt_is_fragmented(pkt))
1650	    {
1651	      /* Copy fragmented packet directly into the next DMA TX buffer.
1652	       * hw_transmit() will set up the descriptor referencing this buffer.
1653	       */
1654	
1655	      unsigned int idx = priv->tx_cur;
1656	      netpkt_copyout(dev, priv->tx_buf[idx], pkt, len, 0);
1657	      data = priv->tx_buf[idx];
1658	    }
1659	  else
1660	    {
1661	      data = netpkt_getdata(dev, pkt);
1662	      if (!data)
1663	        {
1664	          etherr("netpkt_getdata returned NULL\n");
1665	          return -EINVAL;
1666	        }
1667	    }
1668	
1669	  /* Transmit via DMA.  Track the netpkt BEFORE calling hw_transmit
1670	   * (which advances tx_cur) so the ISR can't observe a half-committed
1671	   * slot.  The whole section runs with IRQs off to close the race
1672	   * between pkt store, cur advance, and ISR tx_cleanup.
1673	   *
1674	   * On failure, do NOT free the netpkt — the upper half recycles it.
1675	   */
1676	
1677	  flags = up_irq_save();
1678	  priv->tx_pkt[priv->tx_cur] = pkt;
1679	  ret = hw_transmit(priv, data, len);
1680	  if (ret < 0)
1681	    {
1682	      priv->tx_pkt[priv->tx_cur] = NULL;  /* Undo — slot not consumed */
1683	      up_irq_restore(flags);
1684	      etherr("hw_transmit failed: %d\n", ret);
1685	      return ret;
1686	    }
1687	
1688	  up_irq_restore(flags);
1689	
1690	  return OK;
1691	}
1692	
1693	/****************************************************************************
1694	 * Name: netdriver_receive
1695	 *
1696	 * Description:
1697	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1698	 *   netdev_lower_rxready() was signaled.  Returns one received packet,
1699	 *   or NULL if no more packets are available.
1700	 *
1701	 * Reference: Manual §6, §10.5
1702	 ****************************************************************************/
1703	
1704	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1705	{
1706	  FAR struct sg2000_eth_priv_s *priv =
1707	      (FAR struct sg2000_eth_priv_s *)dev;
1708	  FAR netpkt_t *pkt = NULL;
1709	  struct sg2000_dma_desc_s *desc;
1710	  uintptr_t gmac_base = priv->gmac_base;
1711	  uint32_t status;
1712	  int frame_len;
1713	  int ret;
1714	
1715	  desc = &priv->rx_desc[priv->rx_cur];
1716	
1717	  /* Invalidate descriptor cache line to read DMA-written status */
1718	
1719	  dcache_invalidate_range((uintptr_t)desc,
1720	                          (uintptr_t)desc +
1721	                          sizeof(struct sg2000_dma_desc_s));
1722	
1723	  /* Debug: show RX descriptor status */
1724	
1725	  ethinfo("RX[%u] des0=0x%08" PRIX32 " des1=0x%08" PRIX32
1726	          " des2=0x%08" PRIX32 " OWN=%d\n",
1727	          priv->rx_cur, desc->des0, desc->des1, desc->des2,
1728	          !!(desc->des0 & RDES0_OWN));
1729	
1730	  /* Check if DMA still owns the descriptor (no packet ready) */
1731	
1732	  if (desc->des0 & RDES0_OWN)
1733	    {
1734	      return NULL;
1735	    }
1736	
1737	  status = desc->des0;
1738	
1739	  /* Check for receive errors */
1740	
1741	  if (status & RDES0_ERROR_SUMMARY)
1742	    {
1743	      etherr("RX error status=0x%08" PRIX32 "\n", status);
1744	      goto refill;
1745	    }
1746	
1747	  /* Verify we got a complete frame (first AND last descriptor) */
1748	
1749	  if (!(status & RDES0_FIRST_DESCRIPTOR) ||
1750	      !(status & RDES0_LAST_DESCRIPTOR))
1751	    {
1752	      ethwarn("RX incomplete frame, status=0x%08" PRIX32 "\n", status);
1753	      goto refill;
1754	    }
1755	
1756	  /* Get frame length (includes 4-byte FCS which we strip) */
1757	
1758	  frame_len = (int)((status & RDES0_FRAME_LEN_MASK) >> RDES0_FRAME_LEN_SHIFT)
1759	              - ETH_FCSSLEN;
1760	
1761	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1762	    {
1763	      ethwarn("RX invalid frame length: %d\n", frame_len);
1764	      goto refill;
1765	    }
1766	
1767	  /* Invalidate RX data buffer to read DMA-written data */
1768	
1769	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1770	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1771	                          RX_BUF_SIZE);
1772	
1773	  /* Allocate a netpkt for the received data */
1774	
1775	  pkt = netpkt_alloc(dev, NETPKT_RX);
1776	  if (!pkt)
1777	    {
1778	      etherr("netpkt_alloc failed\n");
1779	      goto refill;
1780	    }
1781	
1782	  /* Copy data from DMA buffer into netpkt */
1783	
1784	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1785	  if (ret < 0)
1786	    {
1787	      etherr("netpkt_copyin failed: %d\n", ret);
1788	      netpkt_free(dev, pkt, NETPKT_RX);
1789	      pkt = NULL;
1790	      goto refill;
1791	    }
1792	
1793	  ethinfo("RX: %d bytes desc[%u]\n", frame_len, priv->rx_cur);
1794	
1795	refill:
1796	  /* Return descriptor to DMA: set OWN=1, restore buffer address.
1797	   * Preserve END_RING bit for the last descriptor in des1.
1798	   */
1799	
1800	  desc->des0 = RDES0_OWN;
1801	  desc->des1 = (RX_BUF_SIZE & RDES1_BUFFER1_SIZE_MASK) |
1802	               ((priv->rx_cur == (RX_RING_SIZE - 1)) ? RDES1_END_RING : 0);
1803	  desc->des2 = priv->rx_buf_phys[priv->rx_cur];
1804	
1805	  /* Flush RX buffer before handing it back to DMA */
1806	
1807	  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1808	                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);
1809	
1810	  /* Write back descriptor so DMA sees OWN=1 */
1811	
1812	  dcache_clean_range((uintptr_t)desc,
1813	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1814	
1815	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1816	  rx_doorbell(gmac_base);
1817	
1818	  return pkt;
1819	}
1820	
1821	/****************************************************************************
1822	 * Private Data — Operations Structure
1823	 ****************************************************************************/
1824	
1825	static const struct netdev_ops_s g_ops =
1826	{
1827	  netdriver_ifup,      /* ifup */
1828	  netdriver_ifdown,    /* ifdown */
1829	  netdriver_transmit,  /* transmit */
1830	  netdriver_receive    /* receive */
1831	};
1832	
1833	/****************************************************************************
1834	 * Public Functions
1835	 ****************************************************************************/
1836	
1837	/****************************************************************************
1838	 * Name: sg2000_eth_initialize
1839	 *
1840	 * Description:
1841	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1842	 *   network stack as a netdev_lowerhalf_s device.
1843	 *
1844	 *   Called from board_late_initialize() during system bringup.
1845	 *
1846	 ****************************************************************************/
1847	
1848	int sg2000_eth_initialize(void)
1849	{
1850	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1851	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1852	  int ret;
1853	
1854	  if (g_eth_initialized)
1855	    {
1856	      return OK;
1857	    }
1858	
1859	  /* Initialize private data */
1860	
1861	  memset(priv, 0, sizeof(*priv));
1862	  priv->gmac_base = SG2000_GMAC_BASE;
1863	  priv->phy_base  = SG2000_EPHY_BASE;
1864	  priv->phy_top   = SG2000_EPHY_TOP;
1865	
1866	  /* Set default MAC address (should be replaced with eFuse/OTP value) */
1867	
1868	  priv->mac_addr[0] = 0x02;
1869	  priv->mac_addr[1] = 0x00;
1870	  priv->mac_addr[2] = 0x00;
1871	  priv->mac_addr[3] = 0x00;
1872	  priv->mac_addr[4] = 0x00;
1873	  priv->mac_addr[5] = 0x01;
1874	
1875	  /* Copy MAC address to the netdev structure */
1876	
1877	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1878	         IFHWADDRLEN);
1879	
1880	  /* Configure device quotas and operations.
1881	   * Total quota (TX + RX) must not exceed CONFIG_IOB_NBUFFERS.
1882	   * With CONFIG_IOB_NBUFFERS=64, we reserve 16 each (32 total).
1883	   */
1884	
1885	  dev->quota[NETPKT_TX] = 16;
1886	  dev->quota[NETPKT_RX] = 16;
1887	  dev->ops              = &g_ops;
1888	
1889	  /* Get the GMAC interrupt number */
1890	
1891	  priv->irq = SG2000_IRQ_GMAC;
1892	
1893	  /* Register with the OpenVela network stack */
1894	
1895	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1896	  if (ret < 0)
1897	    {
1898	      etherr("netdev_lower_register failed: %d\n", ret);
1899	      return ret;
1900	    }
1901	
1902	  /* Initially, carrier is off */
1903	
1904	  netdev_lower_carrier_off(dev);
1905	  g_eth_initialized = true;
1906	
1907	  ethinfo("SG2000 Ethernet driver registered as eth0\n");
1908	
1909	  /* Attach interrupt handler (once).
1910	   * The IRQ is NOT enabled here — it is enabled at the end of
1911	   * netdriver_ifup() only after the hardware is fully configured.
1912	   */
1913	
1914	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1915	  if (ret < 0)
1916	    {
1917	      etherr("irq_attach failed: %d\n", ret);
1918	      return OK;  /* Driver is still registered, just no interrupts */
1919	    }
1920	
1921	  ethinfo("IRQ %d attached (not yet enabled)\n", priv->irq);
1922	
1923	  return OK;
1924	}
1925	
1926	/****************************************************************************
1927	 * Name: riscv_netinitialize
1928	 *
1929	 * Description:
1930	 *   Arch-level network initialization called from up_initialize().
1931	 *   SG2000 Ethernet is initialized from board_late_initialize() instead.
1932	 *
1933	 ****************************************************************************/
1934	
1935	void riscv_netinitialize(void)
1936	{
1937	  /* SG2000 Ethernet needs board-level bringup ordering.  It is initialized
1938	   * from board_late_initialize() after the core OS initialization path.
1939	   */
1940	}
